import {MODES,dateKey,shiftDate,weekStart,seed,leaves,descendants,moveNode,deleteNode,setting,applyPending,plan,toggleLog,ancestry,stats,validate} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let account=null;
try{const response=await fetch('/api/session',{cache:'no-store'});if(response.headers.get('content-type')?.includes('application/json')){const result=await response.json();if(result.mode==='google'){if(!response.ok||!result.user?.id){location.replace('/');throw Error('Authentication required')}account=result.user}}}catch(error){if(error.message==='Authentication required')throw error}
const storageKey=account?'jiku-v1:'+account.id:'jiku-v1';
let needsLegacyImport=false;let state;try{const raw=localStorage.getItem(storageKey);needsLegacyImport=!!account&&!raw&&!!localStorage.getItem('jiku-v1');state=raw?validate(JSON.parse(raw)):seed()}catch{state=seed();setTimeout(()=>toast('保存データを読み込めません。設定からバックアップを確認してください。'),300)}
let view='tree',today=dateKey(),selected=today,month=today.slice(0,7),focus=null,zoom=1,pan={x:0,y:0};
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{toast('保存できませんでした。設定からバックアップを保存してください。')}}
applyPending(state,today);save();
const icon=(name)=>({home:'⌂',tree:'♧',calendar:'▦',stats:'◴',settings:'⚙'}[name]);
const names={tree:'自分の木',calendar:'カレンダー',stats:'統計'};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html){const d=$('#dialog');d.innerHTML=html;d.showModal();d.querySelector('[autofocus]')?.focus()}
function close(){$('#dialog').close()}
function heading(k,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function render(){const latest=dateKey();if(today!==latest){today=latest;selected=today;applyPending(state,today);save()}$('#app').innerHTML=`<main class="workspace view-${view}"><header class="topbar"><a class="brand" href="#tree" aria-label="jiku 自分の木">jiku<span>●</span></a><button class="avatar" data-do="settings" aria-label="設定・バックアップ">${esc(account?.name?.slice(0,1)||'J')}</button></header><div class="content">${({tree:treePage,calendar:calendarPage,stats:statsPage}[view])()}</div></main><nav class="bottom-nav" aria-label="メインメニュー">${Object.entries(names).map(([k,v])=>`<button class="nav ${view===k?'active':''}" data-view="${k}" ${view===k?'aria-current="page"':''}><span aria-hidden="true">${icon(k)}</span><strong>${v}</strong></button>`).join('')}</nav>`;bindTree()}
function modeCards(key){const current=state.records[key]?.mode;return `<div class="mode-grid">${Object.entries(MODES).filter(([k])=>k!=='none').map(([k,m])=>`<button class="mode-card ${current===k?'selected':''} ${k}" data-mode="${k}" data-date="${key}"><span class="mode-icon">${m.icon}</span><span><strong>${m.label}</strong><small>${m.description}</small></span><span class="radio">${current===k?'✓':''}</span></button>`).join('')}</div>`}
function actionRow(n,key){const a=setting(state,n.id),done=!!state.logs[key]?.[n.id];return `<div class="action-row ${done?'done':''}"><button class="check ${done?'checked':''}" data-check="${esc(n.id)}" data-date="${key}" aria-label="${esc(n.name)}の実行記録" aria-pressed="${done}">${done?'✓':''}</button><div class="action-copy"><strong>${esc(n.name)}</strong><small>${esc(ancestry(state,n.id).slice(1,-1).join(' / ')||'自分の木')}</small></div><span class="priority p${a.priority}">${['高','中','低'][a.priority]}</span><button class="edit-action" data-edit="${esc(n.id)}" aria-label="${esc(n.name)}を編集">⋯</button></div>`}
function drawTree(mini=false){const root=state.nodes.find(n=>n.id===(mini?null:focus))||state.nodes.find(n=>n.parentId===null),nodes=[],edges=[];let slot=0;function layout(n,depth){const children=state.nodes.filter(x=>x.parentId===n.id),p={...n,depth};nodes.push(p);if(children.length){const cs=children.map(c=>layout(c,depth+1));p.x=cs.reduce((s,c)=>s+c.x,0)/cs.length;cs.forEach(c=>edges.push([p,c]))}else{p.x=slot++*170}return p}layout(root,0);const maxDepth=Math.max(...nodes.map(n=>n.depth),1),width=Math.max(760,slot*170+100),height=Math.max(480,maxDepth*125+190),maxX=Math.max(...nodes.map(n=>n.x),0);nodes.forEach(n=>{n.x=maxX?105+(width-210)*(n.x/maxX):width/2;n.y=height-90-n.depth*125});const byId=new Map(nodes.map(n=>[n.id,n]));return `<svg class="tree-svg ${mini?'mini':''}" viewBox="0 0 ${width} ${height}" role="group" aria-label="目標と行動を表す自分の木"><defs><linearGradient id="wood${mini?'m':''}" x2="0" y2="1"><stop stop-color="#658c62"/><stop offset="1" stop-color="#89704e"/></linearGradient></defs><g class="tree-transform" transform="${mini?'':`translate(${pan.x} ${pan.y}) scale(${zoom})`}"><ellipse cx="${byId.get(root.id).x}" cy="${height-34}" rx="108" ry="12" fill="#d7debf" opacity=".5"/><path d="M ${byId.get(root.id).x-38} ${height-30} Q ${byId.get(root.id).x} ${height-70} ${byId.get(root.id).x+38} ${height-30}" fill="none" stroke="#a69572" stroke-width="5"/>${edges.map(([a,b])=>`<path d="M ${a.x} ${a.y} C ${a.x} ${b.y+55},${b.x} ${a.y-45},${b.x} ${b.y}" fill="none" stroke="url(#wood${mini?'m':''})" stroke-width="${Math.max(3,16-a.depth*3)}" stroke-linecap="round"/>`).join('')}${nodes.map(n=>{const leaf=!state.nodes.some(x=>x.parentId===n.id),recorded=Object.values(state.logs).some(v=>v[n.id]);return `<g class="tree-node ${leaf?'leaf':'branch'}" ${mini?'':`data-node="${esc(n.id)}" tabindex="0" role="button" aria-label="${esc(n.name)}"`} transform="translate(${n.x},${n.y})"><title>${esc(n.name)}</title>${leaf?`<path d="M 0 3 C -63 15,-70 -55,-8 -45 C 34 -56,60 -6,0 3" fill="${recorded?'#4d8158':'#89a777'}"/><path d="M -27 -27 L 17 -6" stroke="#d5e2bf" stroke-width="1.5"/>`:`<circle r="${n.parentId?9:13}" fill="#7d8b61" stroke="#fafbf4" stroke-width="4"/>`}<rect x="-77" y="${leaf?12:18}" width="154" height="28" rx="14" fill="#fffef9" opacity=".95"/><text text-anchor="middle" y="${leaf?31:37}" fill="#435a43" font-size="12">${esc(n.name.length>13?n.name.slice(0,12)+'…':n.name)}</text></g>`}).join('')}</g></svg>`}
function treePage(){const mode=state.records[today]?.mode;return `<section class="tree-card full-panel" id="goal-tree" aria-label="自分の木"><div class="tree-toolbar"><div class="tree-primary-tools"><button class="primary" data-edit="new">＋ 追加</button><button class="mode-trigger" data-do="today-mode">${mode?`${MODES[mode].icon} ${MODES[mode].label}`:'今日のモード'}</button></div><div class="tree-view-tools"><button data-do="zoom-out" aria-label="縮小">−</button><span>${Math.round(zoom*100)}%</span><button data-do="zoom-in" aria-label="拡大">＋</button><button data-do="reset-tree" aria-label="木の全体表示">全体</button></div></div><div class="tree-canvas">${drawTree()}</div></section>`}
function calendarPage(){const [y,m]=month.split('-').map(Number),first=`${month}-01`,offset=(new Date(first+'T12:00:00+09:00').getUTCDay()+6)%7,num=new Date(Date.UTC(y,m,0)).getUTCDate(),weeks=Math.ceil((num+offset)/7);return `<section class="calendar-card full-panel" aria-label="活動カレンダー"><div class="month-heading"><h1>${y}<small>年</small> ${m}<small>月</small></h1><div><button class="round-button" data-month="-1" aria-label="前の月">←</button><button class="text-button" data-do="today">今月</button><button class="round-button" data-month="1" aria-label="次の月">→</button></div></div><div class="calendar-grid" style="--weeks:${weeks}">${['月','火','水','木','金','土','日'].map(d=>`<span class="day-label">${d}</span>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:num},(_,i)=>{const k=`${month}-${String(i+1).padStart(2,'0')}`,mode=state.records[k]?.mode;return `<button class="day-cell ${selected===k?'selected':''} ${k===today?'today':''}" data-select-date="${k}" aria-label="${m}月${i+1}日 ${MODES[mode]?.label||'未記録'}" ${k>today?'disabled':''}><span>${i+1}</span><i style="background:${MODES[mode]?.color||'#eeede6'}">${mode?MODES[mode].icon:''}</i></button>`}).join('')}</div><div class="legend">${Object.values(MODES).map(m=>`<span><i style="background:${m.color}"></i>${m.label}</span>`).join('')}<span><i style="background:#eeede6"></i>未記録</span></div></section>`}
function dayEditor(key){selected=key;modal(`<div class="dialog-title"><h2>${Number(key.slice(5,7))}月${Number(key.slice(8))}日</h2><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><div class="day-modes">${Object.entries(MODES).map(([k,m])=>`<button class="${state.records[key]?.mode===k?'chosen':''}" data-mode="${k}" data-date="${key}" data-close-after-record><span style="color:${m.color}">${m.icon}</span>${m.label}<i>${state.records[key]?.mode===k?'✓':''}</i></button>`).join('')}</div><button class="text-button quiet" data-do="clear-record">未記録に戻す</button>`)}
function statsPage(){const start=shiftDate(today,-29),s=stats(state,start,today),counts=s.counts;return `<section class="rhythm-panel full-panel" aria-label="日々のモードの割合"><h1>日々のモードの割合</h1><div class="distribution" role="img" aria-label="記録した${s.days}日間のモードの割合">${s.days?Object.entries(counts).map(([k,c])=>`<div style="width:${c/s.days*100}%;background:${MODES[k].color}" title="${MODES[k].label}: ${c}日"></div>`).join(''):'<div style="width:100%;background:#eeede6"></div>'}</div><div class="rhythm-rows">${Object.entries(counts).map(([k,c])=>`<div class="distribution-row"><i style="background:${MODES[k].color}"></i><span>${MODES[k].label}</span><strong>${c}<small>日</small></strong><em>${s.days?Math.round(c/s.days*100):0}%</em></div>`).join('')}</div><p class="footnote">未記録 ${30-s.days} 日は割合に含めていません。</p></section>`}
function editor(id){const isNew=id==='new',n=isNew?{name:'',parentId:focus||state.nodes.find(n=>!n.parentId).id}:state.nodes.find(n=>n.id===id),a=isNew?{priority:1,type:'continuous',status:'active',modes:['full']}:setting(state,id),isRoot=!isNew&&!n.parentId,blocked=isNew?new Set():descendants(state,id),isLeaf=isNew||leaves(state).some(n=>n.id===id);modal(`<form id="node-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">GROW YOUR OWN WAY</div><h2>${isNew?'新しい目標・行動':isRoot?'あなたの根っこ':'目標・行動を編集'}</h2></div><button type="button" data-do="close" class="round-button" aria-label="閉じる">×</button></div><label>名前<input autofocus required maxlength="80" name="name" value="${esc(n.name)}" placeholder="例：自分のアプリをつくる"></label>${!isRoot?`<label>つながる親目標<select name="parent">${state.nodes.filter(p=>!blocked.has(p.id)).map(p=>`<option value="${esc(p.id)}" ${p.id===n.parentId?'selected':''}>${esc(ancestry(state,p.id).join(' / '))}</option>`).join('')}</select></label>`:''}${isLeaf?`<div class="form-divider">葉っぱの行動設定</div><div class="form-columns"><label>種類<select name="type"><option value="continuous" ${a.type==='continuous'?'selected':''}>継続型</option><option value="once" ${a.type==='once'?'selected':''}>完了型</option></select></label><label>優先順位<select name="priority">${['高','中','低'].map((p,i)=>`<option value="${i}" ${i===a.priority?'selected':''}>${p}</option>`).join('')}</select></label></div><label>状態<select name="status">${Object.entries({active:'有効',paused:'一時停止',completed:'完了'}).map(([v,t])=>`<option value="${v}" ${v===a.status?'selected':''}>${t}</option>`).join('')}</select></label><fieldset><legend>実行するモード</legend>${['full','busy','rest'].map(m=>`<label class="checkbox-label"><input type="checkbox" name="modes" value="${m}" ${a.modes.includes(m)?'checked':''}>${MODES[m].icon} ${MODES[m].label}</label>`).join('')}</fieldset><p class="footnote">完了型は実行チェックで完了になります。再開は状態を有効に戻してください。</p>`:'<p class="muted">子目標があるため枝として表示されます。末端の目標が葉っぱになります。</p>'}<div class="dialog-actions">${!isNew&&!isRoot?`<button type="button" class="danger text-button" data-delete="${esc(id)}">削除</button><button type="button" class="text-button" data-focus="${esc(id)}">この枝を見る</button>`:''}<button class="primary" type="submit">${isNew?'追加する':'変更を保存'}</button></div></form>`)}
function review(){const ws=weekStart(today),end=shiftDate(ws,6),s=stats(state,ws,end),r=state.reviews[ws]||{},effective=shiftDate(ws,7);modal(`<form id="review-form"><div class="dialog-title"><div><div class="eyebrow">WEEKLY REFLECTION</div><h2>今週の自分と、話そう。</h2></div><button type="button" data-do="close" class="round-button" aria-label="閉じる">×</button></div><p class="muted">${ws.replaceAll('-','/')} — ${end.replaceAll('-','/')}</p><div class="review-summary">${Object.entries(s.counts).map(([k,c])=>`<div><span style="color:${MODES[k].color}">${MODES[k].icon}</span><strong>${c}日</strong><small>${MODES[k].label}</small></div>`).join('')}</div><h3>今週、取り組んだ葉っぱ</h3><p class="muted">${s.logs.length} 回の実行記録</p>${Object.entries(s.logs.reduce((o,l)=>(o[l.name]=(o[l.name]||0)+1,o),{})).map(([n,c])=>`<p class="review-log">♧ ${esc(n)} <b>${c}回</b></p>`).join('')}<label>無理があったこと・気づいたこと<textarea name="note" rows="3" placeholder="今週の自分に、どんな言葉をかけたい？">${esc(r.note||'')}</textarea></label><label>来週、大切にしたいこと<textarea name="next" rows="2" placeholder="小さく、具体的な一歩を書いてみよう。">${esc(r.next||'')}</textarea></label><h3>来週の行動プラン</h3><p class="footnote">${effective.replaceAll('-','/')}（月）から反映。過去の記録はそのまま残ります。</p>${leaves(state).map(n=>{const a=state.pending.find(p=>p.id===n.id&&p.effective===effective)?.setting||setting(state,n.id);return `<fieldset class="review-setting" data-review-node="${esc(n.id)}"><legend>${esc(n.name)}</legend><select aria-label="${esc(n.name)}の来週の優先順位" data-review-priority>${['高','中','低'].map((p,i)=>`<option value="${i}" ${a.priority===i?'selected':''}>優先順位：${p}</option>`).join('')}</select><div>${['full','busy','rest'].map(m=>`<label class="checkbox-label"><input type="checkbox" value="${m}" ${a.modes.includes(m)?'checked':''}>${MODES[m].label}</label>`).join('')}</div></fieldset>`}).join('')}<div class="dialog-actions"><button class="primary">レビューを保存</button></div></form>`)}
function settings(){modal(`<div class="dialog-title"><div><div class="eyebrow">YOUR OWN GARDEN</div><h2>設定・バックアップ</h2></div><button class="round-button" data-do="close" aria-label="閉じる">×</button></div>${account?`<div class="account-info"><strong>${esc(account.name)}</strong><p>${esc(account.email)}</p><form method="post" action="/api/auth/logout" data-native-submit><button class="text-button" type="submit">ログアウト</button></form></div>`:''}<p>データはこの端末・ブラウザ内に保存されます。端末間での同期はありません。ブラウザのデータを消す前にバックアップしてください。</p><div class="settings-actions"><button class="primary" data-do="export">↓ バックアップを書き出す</button><label class="import-button">↑ バックアップを読み込む<input type="file" id="import" accept="application/json,.json"></label></div><p class="footnote">読み込み時は現在のデータを置き換えます。先に現在のバックアップを保存することをおすすめします。日付は日本時間、週の始まりは月曜日です。</p><hr><p class="muted">jiku v1.0 · 自分の軸を、日々の行動へ。</p>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-do],[data-view],[data-day],[data-focus]');if(!b)return;const d=b.dataset;if(b.hasAttribute('data-scroll-tree')){$('#goal-tree')?.scrollIntoView({behavior:'smooth',block:'start'})}if(d.view){view=d.view;location.hash=view;render();window.scrollTo(0,0)}if(d.mode){state.records[d.date]={mode:d.mode};save();render();close();toast('一日のモードを記録しました')}if(d.check){const n=state.nodes.find(n=>n.id===d.check);if(n){toggleLog(state,d.date,n);save();render()}}if(d.edit)editor(d.edit);if(d.selectDate){selected=d.selectDate;render();dayEditor(selected)}if(d.day){selected=d.day;month=selected.slice(0,7);view='calendar';render()}if(d.month){const [y,m]=month.split('-').map(Number),v=new Date(Date.UTC(y,m-1+Number(d.month),1));month=`${v.getUTCFullYear()}-${String(v.getUTCMonth()+1).padStart(2,'0')}`;render()}if(d.focus){focus=d.focus;zoom=1;pan={x:0,y:0};close();render()}if(d.delete){const id=d.delete,n=state.nodes.find(n=>n.id===id),count=descendants(state,id).size;modal(`<h2>「${esc(n.name)}」を削除しますか？</h2><p>子孫を含め ${count} 個の目標を削除します。過去の実行記録は残ります。</p><div class="dialog-actions"><button class="text-button" data-do="close">キャンセル</button><button class="primary danger-bg" data-confirm-delete="${esc(id)}">削除する</button></div>`)}if(d.confirmDelete){deleteNode(state,d.confirmDelete);focus=null;save();close();render();toast('目標を削除しました')}if(d.do)({close,settings,review,'today-mode':()=>dayEditor(today),'zoom-in':()=>{zoom=Math.min(2.5,zoom+.2);render()},'zoom-out':()=>{zoom=Math.max(.4,zoom-.2);render()},'reset-tree':()=>{focus=null;zoom=1;pan={x:0,y:0};render()},today:()=>{month=today.slice(0,7);selected=today;render()},'clear-record':()=>{delete state.records[selected];save();render();close();toast('モードを未記録に戻しました')},export:()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`jiku-backup-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}[d.do])?.()});
document.addEventListener('submit',e=>{if(e.target.hasAttribute('data-native-submit'))return;e.preventDefault();if(e.target.id==='node-form'){const f=new FormData(e.target),id=e.target.dataset.id,newId=id==='new'?crypto.randomUUID():id,name=f.get('name').trim();if(!name){toast('名前を入力してください');return}try{if(id==='new')state.nodes.push({id:newId,parentId:f.get('parent'),name});else{const n=state.nodes.find(n=>n.id===id);if(n.parentId)moveNode(state,id,f.get('parent'));n.name=name}if(f.has('type'))state.settings[newId]={type:f.get('type'),priority:Number(f.get('priority')),status:f.get('status'),modes:f.getAll('modes')};save();close();render();toast('木を更新しました')}catch(err){toast(err.message)}}if(e.target.id==='review-form'){const ws=weekStart(today),effective=shiftDate(ws,7),f=new FormData(e.target);state.reviews[ws]={note:f.get('note'),next:f.get('next'),savedAt:new Date().toISOString()};e.target.querySelectorAll('[data-review-node]').forEach(el=>{const id=el.dataset.reviewNode;state.pending=state.pending.filter(p=>!(p.id===id&&p.effective===effective));state.pending.push({id,effective,setting:{...setting(state,id),priority:Number(el.querySelector('select').value),modes:[...el.querySelectorAll('input:checked')].map(i=>i.value)}})});save();close();render();toast('レビューを保存しました。行動設定は来週から反映します。')}});
document.addEventListener('change',async e=>{if(e.target.id==='import'&&e.target.files[0]){try{const f=e.target.files[0];if(f.size>10*1024*1024)throw Error('10MB以下のバックアップを選んでください');const next=validate(JSON.parse(await f.text()));modal(`<h2>バックアップを読み込みますか？</h2><p>${next.nodes.length} 個の目標を読み込み、現在のデータを置き換えます。</p><div class="dialog-actions"><button class="text-button" data-do="close">キャンセル</button><button id="confirm-import" class="primary">置き換える</button></div>`);$('#confirm-import').onclick=()=>{state=next;applyPending(state,today);focus=null;save();close();render();toast('バックアップを読み込みました')}}catch(err){toast('読み込めませんでした：'+err.message)}}});
function bindTree(){const canvas=$('.tree-canvas');if(!canvas)return;let start=null,dragging=false;canvas.addEventListener('pointerdown',e=>{const node=e.target.closest('[data-node]');start={x:e.clientX,y:e.clientY,node:node?.dataset.node,pan:{...pan},pointer:e.pointerId};dragging=false});canvas.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>7)dragging=true;if(dragging&&!start.node){const svg=canvas.querySelector('svg'),ratio=svg.viewBox.baseVal.width/canvas.clientWidth;pan={x:start.pan.x+dx*ratio,y:start.pan.y+dy*ratio};svg.querySelector('.tree-transform').setAttribute('transform',`translate(${pan.x} ${pan.y}) scale(${zoom})`)}});window.onpointerup=e=>{if(!start)return;const s=start;start=null;if(s.node){if(!dragging)editor(s.node);else{const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-node]')?.dataset.node;if(target&&target!==s.node){try{moveNode(state,s.node,target);save();render();toast('目標のつながりを変更しました')}catch(err){toast(err.message)}}}}};canvas.addEventListener('keydown',e=>{const id=e.target.closest('[data-node]')?.dataset.node;if(id&&['Enter',' '].includes(e.key)){e.preventDefault();editor(id)}})}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1)==='home'?'tree':location.hash.slice(1);if(names[h]&&view!==h){view=h;render()}});window.addEventListener('focus',()=>{if(dateKey()!==today)render()});if(names[location.hash.slice(1)])view=location.hash.slice(1);if(location.hash==='#home')history.replaceState(null,'','#tree');render();if(needsLegacyImport)offerLegacyImport();

function offerLegacyImport(){modal(`<div class="dialog-title"><h2>以前の記録を引き継ぎますか？</h2></div><p>このブラウザでGoogleログイン前に使っていた記録が残っています。現在ログインしているあなたのアカウントへコピーできます。</p><p class="footnote">元の記録はそのまま残ります。</p><div class="dialog-actions"><button class="text-button" data-do="close">新しく始める</button><button id="copy-legacy" class="primary">記録を引き継ぐ</button></div>`);$('#copy-legacy').onclick=()=>{try{state=validate(JSON.parse(localStorage.getItem('jiku-v1')));applyPending(state,today);save();close();render();toast('以前の記録を引き継ぎました')}catch{toast('以前の記録を読み込めませんでした。バックアップから読み込んでください。')}}}
